import { hostRules, netlifyRedirects } from '../lib/hosts';
import { defineEmitter } from './_types';

// Netlify host file (design doc §9.5; subpath memo §3.3): copy deploy/generated/netlify/_redirects
// to the root of the published directory. Redirects, removed addresses and per-locale 404 pages.
export default defineEmitter({
  name: 'netlify',
  description: 'deploy/generated/netlify/_redirects: redirects and error pages for Netlify',
  run({ content, locales, url, write }) {
    const lines = [
      '# GENERATED by scripts/emitters/netlify.ts. Do not edit; run `npm run content:build`.',
      ...netlifyRedirects(hostRules(content.manifest, url, locales), url, locales),
      '',
    ];
    write('deploy', 'netlify/_redirects', lines.join('\n'));
  },
});
